def transform(grid):
    from collections import Counter
    pixels = [c for r in grid for c in r]
    counts = Counter(pixels)
    bg = counts.most_common(1)[0][0]
    frame = [c for c, v in counts.items() if v == 4][0]
    frame_pos = [(r, c) for r, row in enumerate(grid) for c, val in enumerate(row) if val == frame]
    min_r, max_r = min(p[0] for p in frame_pos), max(p[0] for p in frame_pos)
    min_c, max_c = min(p[1] for p in frame_pos), max(p[1] for p in frame_pos)
    h, w = max_r - min_r + 1, max_c - min_c + 1
    out = [[bg] * w for _ in range(h)]
    out[0][0] = out[0][w-1] = out[h-1][0] = out[h-1][w-1] = frame
    discolors = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != bg and val != frame:
                if val not in discolors: discolors[val] = []
                discolors[val].append((r, c))
    slots = []
    for r in range(h):
        for c in range(w):
            if not ((r == 0 and c == 0) or (r == 0 and c == w-1) or (r == h-1 and c == 0) or (r == h-1 and c == w-1)): slots.append((r, c))
    slots.sort()
    disc_list = []
    for v in discolors:
        for p in discolors[v]: disc_list.append((p[0], p[1], v))
    disc_list.sort()
    for i, (sr, sc, val) in enumerate(disc_list):
        if i < len(slots):
            out[sr][sc] = val
    return out
